css:
.execedsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1c2433;
    background: linear-gradient(165deg, #f3f1ea 0%, #eceadf 100%);
    border-radius: 18px;
}

.execedsim-container * {
    box-sizing: border-box;
}

.execedsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #11203a 0%, #1b3354 55%, #294a73 100%);
    color: #f5f2e8;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(17, 32, 58, 0.32);
    border-bottom: 4px solid #c8a24a;
}

.execedsim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.execedsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #e6cf94;
    background: rgba(200, 162, 74, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
}

.execedsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d8dde6;
}

.execedsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2a3a55;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.execedsim-period-counter #currentDay,
.execedsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #11203a;
}

.execedsim-round-name {
    background: #dfe0d3;
    color: #11203a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.execedsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a5a14;
    background: #f6e9c8;
    padding: 4px 12px;
    border-radius: 999px;
}

.execedsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.execedsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e0ddce;
    box-shadow: 0 4px 14px rgba(17, 32, 58, 0.06);
    border-top: 4px solid #294a73;
}

.execedsim-card-ranking { border-top-color: #294a73; }
.execedsim-card-surplus { border-top-color: #1f7a52; }
.execedsim-card-retention { border-top-color: #b5872a; }
.execedsim-card-util { border-top-color: #7a4f9c; }

.execedsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a7382;
}

.execedsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #11203a;
}

.execedsim-card-ranking .execedsim-value { color: #294a73; }
.execedsim-card-surplus .execedsim-value { color: #1f7a52; }
.execedsim-card-retention .execedsim-value { color: #b5872a; }
.execedsim-card-util .execedsim-value { color: #7a4f9c; }

.execedsim-sublabel {
    font-size: 0.75rem;
    color: #7e8794;
    line-height: 1.35;
}

.execedsim-ranking-safe .execedsim-value { color: #1f7a52; }
.execedsim-ranking-danger .execedsim-value { color: #c0392b; }

.execedsim-surplus-hit .execedsim-value { color: #1f7a52; }
.execedsim-surplus-miss .execedsim-value { color: #c0392b; }

.execedsim-util-over { border-top-color: #c0392b; }
.execedsim-util-over .execedsim-value { color: #c0392b; }

.execedsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #11203a;
    color: #f1eedf;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.execedsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e6cf94;
}

.execedsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c8a24a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(17, 32, 58, 0.05);
}

.execedsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.execedsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #11203a;
    margin-bottom: 6px;
}

.execedsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #34404f;
}

.execedsim-briefing-text strong { color: #1f7a52; }
.execedsim-briefing-text em { color: #8a5a14; font-style: italic; }

.execedsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e0ddce;
    box-shadow: 0 4px 14px rgba(17, 32, 58, 0.06);
}

.execedsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #11203a;
    border-bottom: 2px solid #eceadf;
    padding-bottom: 8px;
}

.execedsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #243349;
    margin: 14px 0 6px;
}

.execedsim-container select,
.execedsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c9cdbb;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbfaf4;
    color: #1c2433;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.execedsim-container select:focus,
.execedsim-container input[type="number"]:focus {
    outline: none;
    border-color: #294a73;
    box-shadow: 0 0 0 3px rgba(41, 74, 115, 0.16);
}

.execedsim-container select option {
    background-color: #ffffff;
    color: #1c2433;
}

.execedsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #294a73;
}

.execedsim-range-readout,
.execedsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #294a73;
    margin-top: 4px;
}

.execedsim-range-readout span:last-child,
.execedsim-alloc-readout span:nth-child(2) {
    color: #1f7a52;
    font-weight: 800;
}

.execedsim-hint {
    font-size: 0.8rem;
    color: #7e8794;
    margin-top: 4px;
    line-height: 1.4;
}

.execedsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.execedsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f6f5ec;
    border: 1px solid #e4e1d2;
    border-radius: 9px;
    padding: 8px 12px;
}

.execedsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #243349;
}

.execedsim-alloc-row input[type="number"] {
    width: 96px;
    flex: 0 0 96px;
}

.execedsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.execedsim-container .btn-primary {
    background: linear-gradient(135deg, #1b3354 0%, #294a73 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #ffffff;
    box-shadow: 0 6px 16px rgba(27, 51, 84, 0.30);
}

.execedsim-container .btn-primary:hover {
    filter: brightness(1.1);
}

.execedsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c9cdbb;
    color: #6a7382;
}

.execedsim-coach {
    background: #11203a;
    color: #eef0e6;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(17, 32, 58, 0.24);
    border-left: 5px solid #c8a24a;
}

.execedsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e6cf94;
    margin-bottom: 8px;
}

.execedsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.execedsim-coach-body strong { color: #f2d98a; }
.execedsim-coach-body em { color: #f0c4a0; font-style: italic; }

.execedsim-history,
.execedsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e0ddce;
    box-shadow: 0 4px 14px rgba(17, 32, 58, 0.06);
}

.execedsim-history h3,
.execedsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #11203a;
}

.execedsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #243349;
}

.execedsim-container table#usfHistoryTable th {
    background: #eceadf;
    color: #11203a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ddd9c8;
}

.execedsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0eee3;
}

.execedsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf9f3;
}

.execedsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .execedsim-container {
        padding: 14px;
    }
    .execedsim-header h1 {
        font-size: 1.7rem;
    }
    .execedsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .execedsim-value {
        font-size: 2rem;
    }
    .execedsim-clock {
        margin-left: 0;
    }
    .execedsim-period-counter {
        font-size: 0.88rem;
    }
    .execedsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .execedsim-alloc-row {
        flex-wrap: wrap;
    }
    .execedsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .execedsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ── v1.1.0 completion debrief (formatCompletionMessage) — append-only, namespaced ── */
.ee-cm {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #26313f;
    background: linear-gradient(165deg, #f3f1ea 0%, #eceadf 100%);
    border: 1px solid #ddd6c6; border-radius: 16px; padding: 22px 24px; margin-top: 8px;
}
.ee-cm-incomplete { font-size: 1rem; color: #6b7280; margin: 0; text-align: center; }
.ee-cm-head { display: flex; flex-wrap: wrap; align-items: stretch; gap: 16px; margin-bottom: 18px; }
.ee-cm-score {
    flex: 1 1 200px; background: linear-gradient(135deg, #11203a 0%, #1b3354 55%, #294a73 100%);
    color: #f4f7fc; border-radius: 14px; padding: 18px 20px; box-shadow: 0 8px 22px rgba(17,32,58,0.28);
}
.ee-cm-score-num { font-size: 2.6rem; font-weight: 800; line-height: 1; letter-spacing: -1px; }
.ee-cm-score-den { font-size: 1.05rem; font-weight: 600; opacity: 0.82; margin-left: 2px; }
.ee-cm-score-lbl { margin-top: 6px; font-size: 0.82rem; text-transform: uppercase; letter-spacing: 0.8px; color: #e7c983; font-weight: 700; }
.ee-cm-verdict {
    flex: 2 1 260px; background: #ffffff; border: 1px solid #ddd6c6; border-left: 5px solid #b5872a;
    border-radius: 14px; padding: 18px 20px; display: flex; flex-direction: column; justify-content: center;
}
.ee-cm-verdict-lbl { font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.9px; color: #6b7280; font-weight: 700; }
.ee-cm-verdict-tier { font-size: 1.5rem; font-weight: 800; color: #11203a; margin-top: 4px; letter-spacing: -0.4px; }
.ee-cm-section { margin-top: 16px; }
.ee-cm-section-h { font-size: 0.82rem; text-transform: uppercase; letter-spacing: 0.9px; color: #294a73; font-weight: 700; margin-bottom: 8px; }
.ee-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.ee-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.86rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.ee-cm-ok { background: #e4f1ea; color: #1f7a52; border-color: #bfe0cd; }
.ee-cm-no { background: #f8e6e3; color: #b23b3b; border-color: #eec7c1; }
.ee-cm-ico { font-weight: 800; }
.ee-cm-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
.ee-cm-kpi { background: #ffffff; border: 1px solid #ddd6c6; border-top: 4px solid #294a73; border-radius: 12px; padding: 12px 14px; text-align: center; }
.ee-cm-kpi:nth-child(1) { border-top-color: #294a73; }
.ee-cm-kpi:nth-child(2) { border-top-color: #1f7a52; }
.ee-cm-kpi:nth-child(3) { border-top-color: #b5872a; }
.ee-cm-kpi:nth-child(4) { border-top-color: #7a4f9c; }
.ee-cm-kpi-val { font-size: 1.5rem; font-weight: 800; color: #11203a; line-height: 1.1; }
.ee-cm-kpi-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.5px; color: #6b7280; font-weight: 700; margin-top: 4px; }
.ee-cm-kpi-sub { font-size: 0.7rem; color: #9aa2ad; margin-top: 3px; }
.ee-cm-insights { margin: 0; padding-left: 20px; }
.ee-cm-insights li { font-size: 0.9rem; color: #3a4656; line-height: 1.5; margin-bottom: 4px; }
@media (max-width: 640px) { .ee-cm-kpis { grid-template-columns: repeat(2, 1fr); } .ee-cm-head { flex-direction: column; } }

