(function() {
    'use strict';

    class ExecEdAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Exec-Ed Strategy`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.START_RANK = 34;          // FT custom rank, was #28
            this.RANK_FLOOR = 40;          // below the top 40 triggers a strategic review
            this.START_RETENTION = 69;     // custom repeat business, was 78%
            this.START_UTIL = 88;          // faculty utilization, near ceiling
            this.SURPLUS_TARGET = 1.5;     // +€1.5M raised target (€M)
            this.BUDGET_CAP = 4.0;         // €4.0M fixed faculty-investment budget (€M)
            this.ANCHOR_VALUE = 3.1;       // €3.1M anchor clients at risk (€M)

            // Concept truths.
            this.TRUE_FUND = `custom`;
            this.TRUE_POSITION = `custom`;
            this.TRUE_DRIVER = `research`;
        }

        _fmtMoney(valM, opts) {
            opts = opts || {};
            const lang = (window.mySimulation && window.mySimulation.language) || `en`;
            const dp = (opts.dp === undefined) ? 1 : opts.dp;
            const signed = !!opts.signed;
            const n = Math.abs(valM);
            const sign = signed ? (valM > 0 ? `+` : (valM < 0 ? `−` : ``)) : (valM < 0 ? `−` : ``);
            if (lang === `es`) {
                const num = n.toFixed(dp).replace(`.`, `,`);
                return `${sign}${num} M€`;
            }
            const num = n.toFixed(dp);
            return `${sign}€${num}M`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    rank: this.START_RANK,
                    surplus: 0,
                    retention: this.START_RETENTION,
                    util: this.START_UTIL,
                    pipeline: 30,
                    budgetUsed: 0,
                    reviewTriggered: false,
                    surplusHit: false,
                    anchorsLost: false,
                    rankHistory: [this.START_RANK],
                    retentionHistory: [this.START_RETENTION],
                    surplusHistory: [0],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seed a middling/neutral mix — NOT the textbook-correct play.
                state.decisions = {
                    fund: `open`,
                    position: `open`,
                    driver: `marketing`,
                    candour: 50,
                    customMix: 40,
                    openMix: 40,
                    qualsMix: 20,
                    action: `hold`,
                    anchorFocus: 40,
                    delivery: 2.5,
                    research: 0.5,
                    devt: 0.5,
                    recruit: 0.5,
                    pricing: `hold`,
                    retentionPlan: `standard`,
                    horizon: `surplus`,
                    sacrifice: `none`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const f = document.getElementById(`fundInput`);
                const p = document.getElementById(`positionInput`);
                const dr = document.getElementById(`driverInput`);
                const c = document.getElementById(`candourInput`);
                if (f) decisions.fund = f.value;
                if (p) decisions.position = p.value;
                if (dr) decisions.driver = dr.value;
                if (c) decisions.candour = parseInt(c.value, 10);
                if (!Number.isFinite(decisions.candour) || decisions.candour < 0 || decisions.candour > 100) {
                    warn(`warn_candour_range`); return false;
                }
            } else if (round === 2) {
                const cm = document.getElementById(`customMixInput`);
                const om = document.getElementById(`openMixInput`);
                const qm = document.getElementById(`qualsMixInput`);
                const ac = document.getElementById(`actionInput`);
                const af = document.getElementById(`anchorFocusInput`);
                if (cm) decisions.customMix = parseFloat(cm.value);
                if (om) decisions.openMix = parseFloat(om.value);
                if (qm) decisions.qualsMix = parseFloat(qm.value);
                if (ac) decisions.action = ac.value;
                if (af) decisions.anchorFocus = parseInt(af.value, 10);
                const parts = [decisions.customMix, decisions.openMix, decisions.qualsMix];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_mix_negative`); return false;
                }
                const total = Math.round(decisions.customMix + decisions.openMix + decisions.qualsMix);
                if (total !== 100) {
                    warn(`warn_mix_total`); return false;
                }
                if (!Number.isFinite(decisions.anchorFocus) || decisions.anchorFocus < 0 || decisions.anchorFocus > 100) {
                    warn(`warn_anchor_range`); return false;
                }
            } else if (round === 3) {
                const de = document.getElementById(`deliveryInput`);
                const re = document.getElementById(`researchInput`);
                const dv = document.getElementById(`devtInput`);
                const rc = document.getElementById(`recruitInput`);
                const pr = document.getElementById(`pricingInput`);
                if (de) decisions.delivery = parseFloat(de.value);
                if (re) decisions.research = parseFloat(re.value);
                if (dv) decisions.devt = parseFloat(dv.value);
                if (rc) decisions.recruit = parseFloat(rc.value);
                if (pr) decisions.pricing = pr.value;
                const allocs = [decisions.delivery, decisions.research, decisions.devt, decisions.recruit];
                if (allocs.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round((decisions.delivery + decisions.research + decisions.devt + decisions.recruit) * 10) / 10;
                if (Math.abs(total - this.BUDGET_CAP) > 0.001) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 4) {
                const rp = document.getElementById(`retentionPlanInput`);
                const ho = document.getElementById(`horizonInput`);
                const sa = document.getElementById(`sacrificeInput`);
                const cv = document.getElementById(`convictionInput`);
                if (rp) decisions.retentionPlan = rp.value;
                if (ho) decisions.horizon = ho.value;
                if (sa) decisions.sacrifice = sa.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Working deltas. positionDelta drives the FT rank (positive = climb = lower number);
            // surplusDelta in €M; retentionDelta in %; utilDelta in %; pipelineDelta builds next year.
            let positionDelta = 0, surplusDelta = 0, retentionDelta = 0, utilDelta = 0, pipelineDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Read the position: custom both FUNDS (high margin) and POSITIONS (ranking) the unit.
                if (d.fund === this.TRUE_FUND) { positionDelta += 1.0; surplusDelta += 0.10; }
                else if (d.fund === `open`) { positionDelta -= 1.0; coachKey = `coach_r1_fundopen`; }
                else { positionDelta -= 1.5; coachKey = `coach_r1_fundquals`; }

                if (d.position === this.TRUE_POSITION) { positionDelta += 1.0; pipelineDelta += 4; }
                else { positionDelta -= 0.5; coachKey = `coach_r1_position`; }

                // Driver of the slide: research output + international participation (an FT input).
                if (d.driver === this.TRUE_DRIVER) {
                    positionDelta += 1.5; pipelineDelta += 4;
                    if (d.fund === this.TRUE_FUND && d.position === this.TRUE_POSITION) coachKey = `coach_r1_sharp`;
                } else if (d.driver === `pricing`) {
                    positionDelta -= 1.5; coachKey = `coach_r1_pricing`;
                } else if (d.driver === `marketing`) {
                    positionDelta -= 1.0; coachKey = `coach_r1_marketing`;
                } else {
                    positionDelta -= 2.5; coachKey = `coach_r1_none`;
                }

                // Candour about the trade-off.
                if (d.candour >= 60) { positionDelta += 0.5; }
                else if (d.candour <= 25) { positionDelta -= 1.5; coachKey = `coach_r1_lowcandour`; }

                summaryKey = (d.fund === this.TRUE_FUND && d.position === this.TRUE_POSITION && d.driver === this.TRUE_DRIVER) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Portfolio mix & capacity under the 88% ceiling (Common Error 3).
                const cm = d.customMix, om = d.openMix, qm = d.qualsMix;

                // A custom-led, leverageable-open, lean-quals mix positions and funds best.
                const customLed = cm >= om && cm >= 40;
                if (customLed) { positionDelta += 1.0; surplusDelta += 0.20; pipelineDelta += 3; }
                else if (om >= 55) { positionDelta -= 1.5; surplusDelta += 0.15; coachKey = `coach_r2_openheavy`; }
                if (qm >= 35) { positionDelta -= 0.5; surplusDelta -= 0.10; coachKey = `coach_r2_qualsheavy`; }
                else if (qm <= 20 && customLed) { surplusDelta += 0.05; }

                // Capacity action against the ceiling.
                switch (d.action) {
                    case `prune`:
                        utilDelta -= 4; surplusDelta += 0.15; positionDelta += 0.5; coachKey = customLed ? `coach_r2_prune` : coachKey; break;
                    case `growall`:
                        utilDelta += 16; surplusDelta += 0.20; positionDelta -= 1.0; coachKey = `coach_r2_growall`; break;
                    case `hold`:
                        utilDelta += 0; coachKey = (coachKey === `coach_default`) ? `coach_r2_hold` : coachKey; break;
                    case `capacity`:
                        utilDelta -= 8; spend += 0.6; pipelineDelta += 4; positionDelta += 0.5; coachKey = `coach_r2_capacity`; break;
                }
                // Growing a custom-led mix still loads faculty unless capacity is freed.
                if (customLed && (d.action === `hold`)) { utilDelta += 9; }
                else if (customLed && d.action === `growall`) { utilDelta += 6; }

                // Designing the mix around the anchors protects €3.1M of custom.
                if (d.anchorFocus >= 60) { retentionDelta += 6; positionDelta += 0.5; }
                else if (d.anchorFocus <= 25) { retentionDelta -= 6; coachKey = `coach_r2_anchorlow`; }

                summaryKey = (customLed && (d.action === `prune` || d.action === `capacity`)) ? `sum_r2_good` : (d.action === `growall` ? `sum_r2_overload` : `sum_r2_weak`);
            } else if (round === 3) {
                // €4.0M faculty investment + pricing (Common Errors 1, 2, 5).
                spend += d.delivery + d.research + d.devt + d.recruit;

                // Delivery funds this year's surplus.
                surplusDelta += d.delivery * 0.24;

                // Research time feeds the FT ranking (non-billable now) — Common Error 5: zero = no pipeline.
                if (d.research >= 0.8) { positionDelta += d.research * 1.5; pipelineDelta += 6; }
                else if (d.research >= 0.4) { positionDelta += d.research * 1.0; pipelineDelta += 3; }
                else { positionDelta -= 1.5; pipelineDelta -= 4; coachKey = `coach_r3_noresearch`; }

                // New-programme development builds next year's pipeline.
                if (d.devt >= 0.6) { pipelineDelta += 7; positionDelta += 0.5; }
                else if (d.devt <= 0.1) { pipelineDelta -= 6; coachKey = (coachKey === `coach_default`) ? `coach_r3_nodevt` : coachKey; }

                // Practitioner recruitment relieves the utilization ceiling.
                if (d.recruit >= 0.5) { utilDelta -= 7; }
                else if (d.recruit <= 0.1) { utilDelta += 3; }

                // Pure-delivery dumping (Common Error 5).
                if (d.delivery >= 3.5) { positionDelta -= 2.5; pipelineDelta -= 6; coachKey = `coach_r3_alldelivery`; }

                // Pricing posture under the positioning constraint (Common Error 2).
                switch (d.pricing) {
                    case `differentiate`:
                        surplusDelta += 0.28; retentionDelta += 3; positionDelta += 0.5; coachKey = (d.research >= 0.8) ? `coach_r3_differentiate` : coachKey; break;
                    case `hold`:
                        surplusDelta += 0.10; break;
                    case `raiseall`:
                        surplusDelta += 0.40; retentionDelta -= 12; positionDelta -= 1.5; coachKey = `coach_r3_raiseall`; break;
                    case `discount`:
                        surplusDelta -= 0.15; retentionDelta += 2; positionDelta -= 2.0; coachKey = `coach_r3_discount`; break;
                }

                summaryKey = (d.research >= 0.8 && d.delivery < 3.5 && d.pricing === `differentiate`) ? `sum_r3_good` : ((d.pricing === `raiseall` || d.delivery >= 3.5) ? `sum_r3_shortterm` : `sum_r3_weak`);
            } else if (round === 4) {
                // Commit & defend (Common Error 4 + strategy-is-sacrifice).
                // Anchor-client retention play.
                switch (d.retentionPlan) {
                    case `value`:
                        retentionDelta += 14; positionDelta += 0.6; surplusDelta += 0.08; coachKey = `coach_r4_value`; break;
                    case `pricematch`:
                        retentionDelta += 6; surplusDelta -= 0.30; positionDelta -= 0.5; coachKey = `coach_r4_pricematch`; break;
                    case `standard`:
                        retentionDelta -= 4; coachKey = `coach_r4_standard`; break;
                    case `ignore`:
                        retentionDelta -= 16; positionDelta -= 1.0; ds.anchorsLost = true; coachKey = `coach_r4_ignore`; break;
                }

                // Horizon defended to the board.
                switch (d.horizon) {
                    case `balanced`:
                        positionDelta += 1.0; pipelineDelta += 4; retentionDelta += 3; coachKey = (d.retentionPlan === `value`) ? `coach_r4_balanced` : coachKey; break;
                    case `surplus`:
                        surplusDelta += 0.25; positionDelta -= 2.0; coachKey = `coach_r4_surplus`; break;
                    case `ranking`:
                        positionDelta += 1.0; surplusDelta -= 0.45; coachKey = `coach_r4_ranking`; break;
                }

                // Strategy is sacrifice (Common Error: no explicit trade-off).
                switch (d.sacrifice) {
                    case `prunequals`:
                        positionDelta += 0.8; surplusDelta += 0.10; utilDelta -= 3; break;
                    case `capopen`:
                        positionDelta += 0.8; retentionDelta += 2; surplusDelta -= 0.08; break;
                    case `none`:
                        positionDelta -= 1.5; pipelineDelta -= 3; coachKey = `coach_r4_nosacrifice`; break;
                }

                // Conviction nudges position.
                positionDelta += (d.conviction - 60) / 35;

                summaryKey = (d.retentionPlan === `value` && d.horizon === `balanced` && d.sacrifice !== `none`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            ds.budgetUsed = Math.round(Math.min(this.BUDGET_CAP, ds.budgetUsed + spend) * 10) / 10;

            // FT rank: positionDelta of +1 climbs roughly one place; bounded clamp keeps headroom.
            const rankBefore = ds.rank;
            ds.rank = Math.max(20, Math.min(48, Math.round((ds.rank - positionDelta) * 10) / 10));

            // Surplus toward the +€1.5M target (€M), retention %, utilization %.
            ds.surplus = Math.round(Math.max(-1.0, ds.surplus + surplusDelta) * 100) / 100;
            ds.retention = Math.max(0, Math.min(100, Math.round((ds.retention + retentionDelta) * 10) / 10));
            ds.util = Math.max(50, Math.round(ds.util + utilDelta));
            ds.pipeline = Math.max(0, Math.min(100, ds.pipeline + pipelineDelta));

            // Escalation: a final position below the FT top 40 triggers the board's strategic review.
            if (round === this.ROUNDS.length) {
                if (ds.rank > this.RANK_FLOOR) ds.reviewTriggered = true;
                if (ds.surplus >= this.SURPLUS_TARGET) ds.surplusHit = true;
                if (ds.retention < this.START_RETENTION - 8 || ds.anchorsLost) ds.anchorsLost = true;
            }

            ds.rankHistory.push(Math.round(ds.rank));
            ds.retentionHistory.push(Math.round(ds.retention));
            ds.surplusHistory.push(Math.round(ds.surplus * 100) / 100);

            // v1.1.0 fix — persist composite where Express grading/reporting reads it
            // (results_utils.php express_resolveDomainScore -> performance.overallScore, then top-level score).
            const composite = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = composite;
            ds.score = composite;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                rank: Math.round(ds.rank),
                rankDelta: Math.round((rankBefore - ds.rank) * 10) / 10,
                surplus: Math.round(ds.surplus * 100) / 100,
                surplusDelta: Math.round(surplusDelta * 100) / 100,
                retention: Math.round(ds.retention),
                retentionDelta: Math.round(retentionDelta * 10) / 10,
                util: Math.round(ds.util),
                pipeline: Math.round(ds.pipeline),
                budgetUsed: ds.budgetUsed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                score: composite,
                overallScore: composite
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            uiManager.bind(`rankingDisplay`, `domainState.rank`, (v) => {
                const card = document.querySelector(`.execedsim-card-ranking`);
                if (card) {
                    card.classList.toggle(`execedsim-ranking-danger`, Number(v) > this.RANK_FLOOR);
                    card.classList.toggle(`execedsim-ranking-safe`, Number(v) <= this.RANK_FLOOR - 4);
                }
                return `#` + Math.round(Number(v));
            });
            uiManager.bind(`surplusDisplay`, `domainState.surplus`, (v) => {
                const card = document.querySelector(`.execedsim-card-surplus`);
                if (card) {
                    card.classList.toggle(`execedsim-surplus-hit`, Number(v) >= this.SURPLUS_TARGET);
                    card.classList.toggle(`execedsim-surplus-miss`, Number(v) < 0);
                }
                return this._fmtMoney(Number(v), { dp: 1, signed: true });
            });
            uiManager.bind(`retentionDisplay`, `domainState.retention`, (v) => Math.round(Number(v)) + `%`);
            uiManager.bind(`utilDisplay`, `domainState.util`, (v) => {
                const card = document.querySelector(`.execedsim-card-util`);
                if (card) card.classList.toggle(`execedsim-util-over`, Number(v) > 100);
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                return this._fmtMoney(Number(v), { dp: 1 }) + ` / ` + this._fmtMoney(this.BUDGET_CAP, { dp: 1 });
            });

            const self = this;

            // Candour slider readout.
            const cand = document.getElementById(`candourInput`);
            const candReadout = document.getElementById(`candourReadout`);
            if (cand && candReadout) {
                candReadout.textContent = cand.value;
                cand.addEventListener(`input`, function() { candReadout.textContent = cand.value; });
            }

            // Anchor-focus slider readout.
            const af = document.getElementById(`anchorFocusInput`);
            const afReadout = document.getElementById(`anchorFocusReadout`);
            if (af && afReadout) {
                afReadout.textContent = af.value;
                af.addEventListener(`input`, function() { afReadout.textContent = af.value; });
            }

            // Capacity-mix live total (must equal 100%).
            const mixIds = [`customMixInput`, `openMixInput`, `qualsMixInput`];
            const mixReadout = document.getElementById(`mixReadout`);
            const recomputeMix = function() {
                let total = 0;
                mixIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (mixReadout) mixReadout.textContent = total;
                const bar = mixReadout ? mixReadout.closest(`.execedsim-alloc-readout`) : null;
                if (bar) bar.style.color = (total !== 100) ? `#c0392b` : ``;
            };
            mixIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recomputeMix);
            });
            recomputeMix();

            // Budget allocation live total (must equal €4.0M).
            const allocIds = [`deliveryInput`, `researchInput`, `devtInput`, `recruitInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recomputeAlloc = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (allocReadout) allocReadout.textContent = total.toFixed(1);
                const bar = allocReadout ? allocReadout.closest(`.execedsim-alloc-readout`) : null;
                if (bar) bar.style.color = (Math.abs(total - self.BUDGET_CAP) > 0.001) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recomputeAlloc);
            });
            recomputeAlloc();
        }

        getChartConfig() {
            const t = (k) => (window.mySimulation ? window.mySimulation.t(k) : k);
            return {
                execedChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: t(`chart_rank`),
                                data: [],
                                borderColor: `#294a73`,
                                backgroundColor: `rgba(41,74,115,0.12)`,
                                borderWidth: 3,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#294a73`,
                                yAxisID: `yRank`
                            },
                            {
                                label: t(`chart_retention`),
                                data: [],
                                borderColor: `#b5872a`,
                                backgroundColor: `rgba(181,135,42,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#b5872a`,
                                yAxisID: `yPct`
                            },
