        getChartData(state) {
            const ds = state.domainState;
            const t = (k) => (window.mySimulation ? window.mySimulation.t(k) : k);
            const labels = ds.rankHistory.map((_, i) => (i === 0 ? t(`chart_start`) : `R` + i));
            return {
                execedChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.rankHistory },
                        { data: ds.retentionHistory },
                        { data: ds.surplusHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            // Verbatim v1.0.0 composite (was inline in getPerformanceSummary), extracted so the
            // per-period persisted score and the completion summary are identical by construction.
            const rank = Math.round(ds.rank);
            const surplus = Math.round(ds.surplus * 100) / 100;
            const retention = Math.round(ds.retention);
            const util = Math.round(ds.util);
            const pipeline = Math.round(ds.pipeline);
            const staffable = util <= 100;
            const rankScore = Math.max(0, Math.min(100, (48 - rank) / (48 - 20) * 100));
            const surplusScore = Math.max(0, Math.min(100, (surplus + 0.5) / (this.SURPLUS_TARGET + 0.5) * 100));
            const retScore = Math.max(0, Math.min(100, (retention - 55) / (85 - 55) * 100));
            const utilPenalty = staffable ? 0 : Math.min(30, (util - 100) * 2);
            return Math.round(rankScore * 0.32 + surplusScore * 0.26 + retScore * 0.24 + pipeline * 0.18 - utilPenalty);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const rank = Math.round(ds.rank);
            const surplus = Math.round(ds.surplus * 100) / 100;
            const retention = Math.round(ds.retention);
            const util = Math.round(ds.util);
            const pipeline = Math.round(ds.pipeline);

            const heldRanking = rank <= this.RANK_FLOOR;
            const hitSurplus = surplus >= this.SURPLUS_TARGET;
            const keptAnchors = !ds.anchorsLost && retention >= this.START_RETENTION;
            const staffable = util <= 100;

            // Composite: position (rank), surplus, retention, capacity reality, pipeline.
            const rankScore = Math.max(0, Math.min(100, (48 - rank) / (48 - 20) * 100));
            const surplusScore = Math.max(0, Math.min(100, (surplus + 0.5) / (this.SURPLUS_TARGET + 0.5) * 100));
            const retScore = Math.max(0, Math.min(100, (retention - 55) / (85 - 55) * 100));
            const utilPenalty = staffable ? 0 : Math.min(30, (util - 100) * 2);
            const composite = this._composite(ds);

            // v1.1.0 fix — tier labels were hardcoded English; now i18n-keyed (localized es).
            let tierKey = `grade_review`;
            if (heldRanking && hitSurplus && keptAnchors && staffable && composite >= 70) tierKey = `grade_sustainable`;
            else if (heldRanking && hitSurplus && keptAnchors && staffable) tierKey = `grade_balanced`;
            else if (hitSurplus && !heldRanking) tierKey = `grade_bought`;
            else if (heldRanking && !hitSurplus) tierKey = `grade_heldbrand`;
            else if (!staffable) tierKey = `grade_unstaffable`;
            else if (!heldRanking) tierKey = `grade_review`;
            else tierKey = `grade_mixed`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (heldRanking && hitSurplus && keptAnchors && staffable) insights.push(window.mySimulation.t(`insight_balanced`));
            else if (hitSurplus && !heldRanking) insights.push(window.mySimulation.t(`insight_surpluswon`));
            else if (heldRanking && !hitSurplus) insights.push(window.mySimulation.t(`insight_surplusshort`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!staffable) insights.push(window.mySimulation.t(`insight_unstaffable`));
            if (ds.anchorsLost) insights.push(window.mySimulation.t(`insight_anchorslost`));
            if (ds.reviewTriggered) insights.push(window.mySimulation.t(`insight_review`));
            if (pipeline < 30) insights.push(window.mySimulation.t(`insight_nopipeline`));
            if (heldRanking && hitSurplus && keptAnchors && staffable && pipeline >= 50) insights.push(window.mySimulation.t(`insight_pipeline`));

            return {
                rank: rank,
                surplus: surplus,
                retention: retention,
                util: util,
                pipeline: pipeline,
                heldRanking: heldRanking,
                hitSurplus: hitSurplus,
                keptAnchors: keptAnchors,
                staffable: staffable,
                composite: composite,
                performance: performance,
                performanceKey: tierKey,
                budgetUsed: ds.budgetUsed,
                onBudget: ds.budgetUsed <= this.BUDGET_CAP,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="ee-cm"><p class="ee-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const lang = (window.mySimulation && window.mySimulation.language) || `en`;
            const surplusTxt = (lang === `es`)
                ? (Math.round(s.surplus * 10) / 10).toFixed(1).replace(`.`, `,`) + ` M€`
                : `€` + (Math.round(s.surplus * 10) / 10).toFixed(1) + `M`;
            const chip = (ok, label) => `<span class="ee-cm-chip ` + (ok ? `ee-cm-ok` : `ee-cm-no`) + `">` +
                `<span class="ee-cm-ico">` + (ok ? `\u2713` : `\u2715`) + `</span>` + label + ` \u00b7 ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="ee-cm-kpi"><div class="ee-cm-kpi-val">` + val +
                `</div><div class="ee-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="ee-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="ee-cm">` +
  `<div class="ee-cm-head">` +
    `<div class="ee-cm-score"><div class="ee-cm-score-num">` + Math.round(s.composite) +
       `<span class="ee-cm-score-den">/100</span></div>` +
       `<div class="ee-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="ee-cm-verdict"><div class="ee-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="ee-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="ee-cm-section"><div class="ee-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="ee-cm-chips">` + chip(s.heldRanking, t(`cm_t_rank`)) + chip(s.hitSurplus, t(`cm_t_surplus`)) +
      chip(s.keptAnchors, t(`cm_t_anchors`)) + chip(s.staffable, t(`cm_t_staff`)) + `</div></div>` +
  `<div class="ee-cm-section"><div class="ee-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="ee-cm-kpis">` +
      kpi(t(`ranking_label`), `#` + Math.round(s.rank), t(`cm_sub_rank`)) +
      kpi(t(`surplus_label`), surplusTxt, t(`cm_sub_surplus`)) +
      kpi(t(`retention_label`), Math.round(s.retention) + `%`, t(`cm_sub_ret`)) +
      kpi(t(`util_label`), Math.round(s.util) + `%`, t(`cm_sub_util`)) +
    `</div></div>` +
