        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.util > 100) return window.mySimulation.t(`hint_unstaffable`);
            if (ds.rank > this.RANK_FLOOR && state.currentPeriod >= 2) return window.mySimulation.t(`hint_ranking`);
            if (ds.retention < this.START_RETENTION - 6) return window.mySimulation.t(`hint_anchors`);
            if (state.currentPeriod >= 3 && ds.surplus < 0.6) return window.mySimulation.t(`hint_surplus`);
            if (ds.pipeline < 25) return window.mySimulation.t(`hint_pipeline`);
            if (ds.rank <= this.RANK_FLOOR - 2 && ds.surplus >= this.SURPLUS_TARGET && ds.retention >= this.START_RETENTION) return window.mySimulation.t(`hint_strong`);
            return null;
        }

